$ErrorActionPreference='Stop'
$case='K:\70.ArasUpgradeCases\芯洲'
$ids=@('customer-11sp9','ootb-11sp9','ootb-r38');$vers=@('11.0 SP9','11.0 SP9','R38');$names=@('version-primary.md','integrity.md','integrity.sha256','source-provenance.md')
$stage=Join-Path -Path $case -ChildPath ('.orchestrator\evidence-staging-'+[guid]::NewGuid().ToString('N'));$stamp=(Get-Date).ToUniversalTime().ToString('o')
function Rel($t,$f){$a=[IO.Path]::GetFullPath($t).TrimEnd([char]92);$b=[IO.Path]::GetFullPath($f);$p=$a+[char]92;if(!$b.StartsWith($p,[StringComparison]::OrdinalIgnoreCase)){throw 'Outside Tree'};$b.Substring($p.Length).Replace([char]92,[char]47)}
$plan=@();for($i=0;$i -lt 3;$i++){$t=Join-Path -Path $case -ChildPath ('core-tree\inputs\'+$ids[$i]+'\tree');$e=Join-Path -Path $case -ChildPath ('core-tree\inputs\'+$ids[$i]+'\evidence');if(!(Test-Path -LiteralPath $t)){throw 'Tree missing'};if(!(Test-Path -LiteralPath (Join-Path -Path $t -ChildPath 'Innovator\Client')) -or !(Test-Path -LiteralPath (Join-Path -Path $t -ChildPath 'Innovator\Server'))){throw 'Client or Server missing'};$old=@($names|Where-Object{Test-Path -LiteralPath (Join-Path -Path $e -ChildPath $_)});if($old.Count){throw 'Evidence is not Missing'};$plan+=@{I=$ids[$i];V=$vers[$i];T=$t;E=$e}}
try{foreach($p in $plan){$sd=Join-Path -Path $stage -ChildPath $p.I;[IO.Directory]::CreateDirectory($sd)|Out-Null;$fs=@(Get-ChildItem -LiteralPath $p.T -File -Recurse -Force|Sort-Object FullName);$lines=@($fs|ForEach-Object{(Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash.ToLowerInvariant()+'  '+(Rel $p.T $_.FullName)});$iom=Join-Path -Path $p.T -ChildPath 'Innovator\Server\bin\IOM.dll';$iv=(Get-Item -LiteralPath $iom).VersionInfo;$c=@{};$c['version-primary.md']="# Version Primary`r`n`r`n- Input: $($p.I)`r`n- Version: $($p.V)`r`n- Build: <PENDING>`r`n- Edition: Enterprise (case default)`r`n- IOM.dll FileVersion: $($iv.FileVersion)`r`n- IOM.dll ProductVersion: $($iv.ProductVersion)`r`n- IOM.dll path: $iom`r`n- Collector: BCO\kenny`r`n- Collected at UTC: $stamp`r`n- Status: Pending";$c['integrity.md']="# Integrity`r`n`r`n- Input: $($p.I)`r`n- Tree root: $($p.T)`r`n- File count: $($fs.Count)`r`n- SHA-256 list: integrity.sha256`r`n- IOM.dll FileVersion: $($iv.FileVersion)`r`n- IOM.dll ProductVersion: $($iv.ProductVersion)`r`n- Build: <PENDING>`r`n- Status: Pending";$c['integrity.sha256']=($lines -join "`r`n")+"`r`n";$c['source-provenance.md']="# Source Provenance`r`n`r`n- Input: $($p.I)`r`n- Destination: $($p.T)`r`n- Original source: <PENDING>`r`n- Copy or export method: <PENDING>`r`n- Copied at UTC: <PENDING>`r`n- Copied by: <PENDING>`r`n- Related evidence: version-primary.md; integrity.md; integrity.sha256; source-provenance.md`r`n- Status: Pending";foreach($q in $names){[IO.File]::WriteAllText((Join-Path -Path $sd -ChildPath $q),$c[$q],[Text.UTF8Encoding]::new($true))};$check=@(Get-ChildItem -LiteralPath $p.T -File -Recurse -Force|Sort-Object FullName|ForEach-Object{(Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash.ToLowerInvariant()+'  '+(Rel $p.T $_.FullName)});if(($check -join "`n") -ne ($lines -join "`n")){throw 'Hash mismatch'}};foreach($p in $plan){$sd=Join-Path -Path $stage -ChildPath $p.I;[IO.Directory]::CreateDirectory($p.E)|Out-Null;foreach($q in $names){$d=Join-Path -Path $p.E -ChildPath $q;if(Test-Path -LiteralPath $d){throw 'Refusing overwrite'};[IO.File]::Move((Join-Path -Path $sd -ChildPath $q),$d)}};Write-Output 'WRITE=SUCCESS';Write-Output 'FILES_CREATED=12'}catch{Write-Output ('WRITE=FAILED: '+$_.Exception.Message);Write-Output ('STAGING='+$stage);throw}
